#include <iostream>
#include <string_view>

// Procedural style function (C-compatible)
int proceduralAdd(int a, int b) {
    return a + b;
}

// Generic style template function (C++ feature)
template <typename T>
T genericAdd(T a, T b) {
    return a + b;
}

int main() {
    constexpr std::string_view langName = "C++17";
    std::cout << "Welcome to modern " << langName << "!\n";

    int sum1 = proceduralAdd(15, 25);
    double sum2 = genericAdd(12.5, 7.5);

    std::cout << "Procedural sum: " << sum1 << "\n";
    std::cout << "Generic sum: " << sum2 << "\n";
    return 0;
}

#include <iostream>

int main() {
    // Prompting and reading first integer
    std::cout << "Enter first integer: ";
    int number1{0};
    std::cin >> number1;

    // Prompting and reading second integer
    std::cout << "Enter second integer: ";
    int number2{0};
    std::cin >> number2;

    // Variable declaration at point of use
    int sum{number1 + number2};

    // Chained output with std::endl
    std::cout << "Sum is " << sum << std::endl;

    return 0;
}
